// Minecraft-style box models (geometry table is generated by tools/content/mobs.py -> model_defs.h).
#ifndef MODEL_H
#define MODEL_H
#include "../core/common.h"
#include "../gfx/gfx.h"
#include "../gen/content.h"

typedef struct { int role, u, v; f32 box[3], size[3], pivot[3], rot[3]; int idx; } ModelPartDef;
typedef struct { const char *name; int tw, th; const ModelPartDef *parts; int n; } ModelDef;

typedef struct {
    f32 head_yaw, head_pitch;   // radians, relative to the body
    f32 limb_swing, limb_amount;
    f32 attack;                 // 0..1 arm swing progress
    f32 age;                    // ticks, for idle motion
    bool arms_forward;          // zombie pose
    bool airborne;              // wings flap
    bool swimming;              // tails/fins beat faster
    f32 bow_aim;                // skeleton aiming 0..1
    f32 jaw;                    // 0..1 open
} ModelPose;

// Draws a model with b3d (texture must already be bound with b3d_set_texture).
void model_draw(int model, mat4 world, const ModelPose *pose, u32 color, f32 tex_w, f32 tex_h);
// Draws a single part (used for the first-person arm).
void model_draw_part(int model, int part_index, mat4 world, u32 color, f32 tex_w, f32 tex_h);
const ModelDef *model_def(int model);
#endif
